#!/usr/bin/env pwsh\n<#\n.SYNOPSIS\n    RAG Application - Full Connectivity Diagnostic Test\n    Verifies all services are running and properly connected\n\n.DESCRIPTION\n    This script tests connectivity between all components:\n    - Ollama service\n    - FastAPI backend  \n    - Node.js frontend\n    - Full end-to-end RAG pipeline\n\n.EXAMPLE\n    .\\test-connectivity.ps1\n#>\n\nWrite-Host \"🧪 RAG Application Connectivity Test\" -ForegroundColor Cyan\nWrite-Host \"====================================\" -ForegroundColor Cyan\nWrite-Host \"\"\n\n$script:passed = 0\n$script:failed = 0\n$script:warnings = 0\n\nfunction Test-Service {\n    param(\n        [string]$Name,\n        [string]$Url,\n        [string]$Method = \"GET\",\n        [hashtable]$Headers = @{},\n        [string]$Body = \"\",\n        [int]$Timeout = 5000\n    )\n    \n    Write-Host \"Testing: $Name\" -ForegroundColor Yellow\n    Write-Host \"  URL: $Url\" -ForegroundColor Gray\n    \n    try {\n        $params = @{\n            Uri = $Url\n            Method = $Method\n            Headers = $Headers\n            TimeoutSec = 5\n            ErrorAction = \"Stop\"\n        }\n        \n        if ($Body) {\n            $params[\"Body\"] = $Body\n        }\n        \n        $response = Invoke-WebRequest @params\n        \n        Write-Host \"  ✅ PASS - Status: $($response.StatusCode)\" -ForegroundColor Green\n        Write-Host \"     Response size: $($response.Content.Length) bytes\" -ForegroundColor Gray\n        \n        $script:passed++\n        return $true\n    } catch {\n        $errorMsg = $_.Exception.Message\n        if ($errorMsg -like \"*Connection refused*\" -or $errorMsg -like \"*Cannot connect*\") {\n            Write-Host \"  ❌ FAIL - Service not running or unreachable\" -ForegroundColor Red\n            Write-Host \"     Error: $errorMsg\" -ForegroundColor Red\n        } elseif ($errorMsg -like \"*timeout*\" -or $errorMsg -like \"*timed out*\") {\n            Write-Host \"  ⚠️  WARN - Service timeout (may be slow)\" -ForegroundColor Yellow\n            Write-Host \"     Error: $errorMsg\" -ForegroundColor Yellow\n            $script:warnings++\n            return $false\n        } else {\n            Write-Host \"  ❌ FAIL - $errorMsg\" -ForegroundColor Red\n        }\n        \n        $script:failed++\n        return $false\n    }\n    Write-Host \"\"\n}\n\nfunction Test-Port {\n    param(\n        [string]$Host,\n        [int]$Port,\n        [string]$ServiceName\n    )\n    \n    Write-Host \"Testing: $ServiceName (Port $Port)\" -ForegroundColor Yellow\n    \n    try {\n        $tcpClient = New-Object System.Net.Sockets.TcpClient\n        $tcpClient.ConnectAsync($Host, $Port).Wait(3000) | Out-Null\n        \n        if ($tcpClient.Connected) {\n            Write-Host \"  ✅ PASS - Port is open and listening\" -ForegroundColor Green\n            $tcpClient.Close()\n            $script:passed++\n            return $true\n        } else {\n            Write-Host \"  ❌ FAIL - Port is not accepting connections\" -ForegroundColor Red\n            $script:failed++\n            return $false\n        }\n    } catch {\n        Write-Host \"  ❌ FAIL - Connection error: $($_.Exception.Message)\" -ForegroundColor Red\n        $script:failed++\n        return $false\n    }\n    Write-Host \"\"\n}\n\n# Test 1: Ollama Service\nWrite-Host \"1️⃣  OLLAMA SERVICE\" -ForegroundColor Cyan\nWrite-Host \"   ==================\" -ForegroundColor Cyan\nTest-Port \"127.0.0.1\" 11434 \"Ollama Port\"\nTest-Service \"Ollama API\" \"http://127.0.0.1:11434/api/tags\" \"GET\" @{}\nWrite-Host \"\"\n\n# Test 2: FastAPI Backend\nWrite-Host \"2️⃣  FASTAPI BACKEND\" -ForegroundColor Cyan\nWrite-Host \"   ==================\" -ForegroundColor Cyan\nTest-Port \"127.0.0.1\" 8000 \"FastAPI Port\"\nTest-Service \"FastAPI Health\" \"http://127.0.0.1:8000/docs\" \"GET\" @{}\nWrite-Host \"\"\n\n# Test 3: Query Endpoint\nWrite-Host \"3️⃣  RAG QUERY ENDPOINT\" -ForegroundColor Cyan\nWrite-Host \"   =====================\" -ForegroundColor Cyan\nWrite-Host \"Testing: FastAPI /query endpoint\" -ForegroundColor Yellow\n$queryBody = @{\n    query = \"test query\"\n    model = \"llama3\"\n    top_k = 5\n} | ConvertTo-Json\n\nif (Test-Service \"RAG Query\" \"http://127.0.0.1:8000/query\" \"POST\" @{\"Content-Type\"=\"application/json\"} $queryBody) {\n    Write-Host \"\"\n} else {\n    Write-Host \"  (This may fail if no documents are ingested - that's normal)\" -ForegroundColor Gray\n    Write-Host \"\"\n}\n\n# Test 4: Node.js Frontend\nWrite-Host \"4️⃣  NODE.JS FRONTEND\" -ForegroundColor Cyan\nWrite-Host \"   ==================\" -ForegroundColor Cyan\nTest-Port \"127.0.0.1\" 3010 \"Node.js Port\"\nTest-Service \"Frontend HTML\" \"http://127.0.0.1:3010\" \"GET\" @{}\nWrite-Host \"\"\n\n# Test 5: Frontend API Endpoints\nWrite-Host \"5️⃣  FRONTEND API PROXY\" -ForegroundColor Cyan\nWrite-Host \"   ====================\" -ForegroundColor Cyan\nTest-Service \"Frontend /insights\" \"http://127.0.0.1:3010/api/insights\" \"GET\" @{}\nTest-Service \"Frontend /schemes\" \"http://127.0.0.1:3010/api/schemes\" \"GET\" @{}\nWrite-Host \"\"\n\n# Test 6: End-to-End Chat\nWrite-Host \"6️⃣  END-TO-END CHAT\" -ForegroundColor Cyan\nWrite-Host \"   =================\" -ForegroundColor Cyan\nWrite-Host \"Testing: Complete chat pipeline\" -ForegroundColor Yellow\n$chatBody = @{\n    message = \"What is agriculture?\"\n} | ConvertTo-Json\n\nif (Test-Service \"Frontend Chat\" \"http://127.0.0.1:3010/api/chat\" \"POST\" @{\"Content-Type\"=\"application/json\"} $chatBody) {\n    Write-Host \"    (Chat routed through Node.js to FastAPI to Ollama)\" -ForegroundColor Gray\n    Write-Host \"\"\n}\n\n# Summary\nWrite-Host \"====================================\" -ForegroundColor Cyan\nWrite-Host \"📊 TEST SUMMARY\" -ForegroundColor Cyan\nWrite-Host \"====================================\" -ForegroundColor Cyan\n\nWrite-Host \"  ✅ Passed: $script:passed\" -ForegroundColor Green\nif ($script:warnings -gt 0) {\n    Write-Host \"  ⚠️  Warnings: $script:warnings\" -ForegroundColor Yellow\n}\nif ($script:failed -gt 0) {\n    Write-Host \"  ❌ Failed: $script:failed\" -ForegroundColor Red\n}\n\nWrite-Host \"\"\n\nif ($script:failed -eq 0 -and $script:warnings -eq 0) {\n    Write-Host \"✅ ALL TESTS PASSED!\" -ForegroundColor Green\n    Write-Host \"Your RAG application stack is fully connected and ready to use.\" -ForegroundColor Green\n    Write-Host \"Access the application at: http://localhost:3010\" -ForegroundColor Green\n} elseif ($script:failed -eq 0) {\n    Write-Host \"⚠️  TESTS PASSED WITH WARNINGS\" -ForegroundColor Yellow\n    Write-Host \"The application should work, but may be slow or unstable.\" -ForegroundColor Yellow\n} else {\n    Write-Host \"❌ SOME TESTS FAILED\" -ForegroundColor Red\n    Write-Host \"Please check the failed tests above and ensure all services are running:\" -ForegroundColor Red\n    Write-Host \"  1. Ollama: ollama serve\" -ForegroundColor Gray\n    Write-Host \"  2. FastAPI: uvicorn app:app --reload --host 127.0.0.1 --port 8000\" -ForegroundColor Gray\n    Write-Host \"  3. Node.js: node server.js\" -ForegroundColor Gray\n}\n\nWrite-Host \"\"\nWrite-Host \"For help, see:\" -ForegroundColor Cyan\nWrite-Host \"  - README.md (full documentation)\" -ForegroundColor Gray\nWrite-Host \"  - STARTUP_GUIDE.md (setup instructions)\" -ForegroundColor Gray\n"